// Provided: a binary tree node.
public class TreeNode {
    public int Value; public TreeNode Left, Right;
    public TreeNode(int value) { Value = value; }
}

// LeetCode 297 — turn a tree into a string and back. Level order, "#" for a missing child.
// Iterative both ways, so a very deep (one-sided) tree cannot overflow the stack.
public static class TreeCodec {
    public static string Serialize(TreeNode root) {
        if (root == null) return "";
        var parts = new List<string>();
        var queue = new Queue<TreeNode>();
        queue.Enqueue(root);
        while (queue.Count > 0) {
            var node = queue.Dequeue();
            if (node == null) { parts.Add("#"); continue; }
            parts.Add(node.Value.ToString());
            queue.Enqueue(node.Left);          // children are written even when missing ("#")
            queue.Enqueue(node.Right);
        }
        int end = parts.Count;                 // trailing "#"s carry no information
        while (end > 0 && parts[end - 1] == "#") end--;
        return string.Join(",", parts.GetRange(0, end));
    }

    public static TreeNode Deserialize(string data) {
        if (string.IsNullOrEmpty(data)) return null;
        string[] parts = data.Split(',');
        var root = new TreeNode(int.Parse(parts[0]));
        var queue = new Queue<TreeNode>();
        queue.Enqueue(root);
        int i = 1;
        while (queue.Count > 0 && i < parts.Length) {   // read children in the same order they were written
            var node = queue.Dequeue();
            if (i < parts.Length && parts[i] != "#") { node.Left = new TreeNode(int.Parse(parts[i])); queue.Enqueue(node.Left); }
            i++;
            if (i < parts.Length && parts[i] != "#") { node.Right = new TreeNode(int.Parse(parts[i])); queue.Enqueue(node.Right); }
            i++;
        }
        return root;
    }
}
